'use strict';

/**
 * Conteúdo programático por matéria: assuntos (topics) e subassuntos (subtopics),
 * com o mapeamento de quais provas cobram cada assunto (tabela exam_topics).
 *
 * Formato: { [subjectSlug]: [ { slug, name, description, subtopics: [nomes], exams: [slugs], weight? } ] }
 *
 * Regras:
 *  - Um assunto existe UMA vez e é vinculado a várias provas — nunca duplique
 *    "Porcentagem" por prova; acrescente a prova em `exams`.
 *  - `slug` é único dentro da matéria (chave de idempotência do seed).
 *  - `weight` (opcional, padrão 1.0) é o peso do assunto na prova, usado pelo
 *    cronograma para priorizar assuntos de alta incidência.
 *  - A ordem dos assuntos é a ordem sugerida de estudo (sort_order no banco).
 *  - Subassuntos são gerados a partir dos nomes (slug derivado); o admin pode
 *    reordená-los, renomeá-los ou criar novos no painel de conteúdo.
 */

const ENEM = 'enem';
const BB = 'barro-branco';
const VEST = ['fuvest', 'unicamp', 'unesp', 'fgv', 'mackenzie', 'puc-sp'];
