const HUMANAS_SOCIAIS = [ENEM, BB, 'fuvest', 'unicamp', 'unesp']; // Filosofia e Sociologia

/** Atalho para declarar um assunto. */
function t(slug, name, description, subtopics, exams = ALL, weight) {
  const topic = { slug, name, description, subtopics, exams };
  if (weight) topic.weight = weight;
  return topic;
}

